reduction.template_c:
#pragma omp parallel for reduction({op}:{var})
for (...) {
    {var} {op}= expr;
}

private_clause.template_c:
#pragma omp parallel for private({var})
for (...) {
    {var} = ...;  // each thread has its own copy
}

declare_inside_loop.template_c:
#pragma omp parallel for
for (int i = 0; i < N; i++) {
    int {var} = ...;  // now private to each iteration
}

barrier.template_c:
// Phase 1: produce
#pragma omp barrier
// Phase 2: consume

consistent_lock_order.template_c:
// Always acquire in order: lock_A before lock_B
omp_set_lock(&lock_A);
omp_set_lock(&lock_B);
// ... critical section ...
omp_unset_lock(&lock_B);
omp_unset_lock(&lock_A);

padding.template_c:
#define PAD 16  // 64 bytes / sizeof(int)
int counters[NUM_THREADS * PAD];
// Access: counters[tid * PAD]
